import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Formik, Form, Field, ErrorMessage } from 'formik';
import * as Yup from 'yup';
import styled from 'styled-components';
import authService from '../services/authService';

const LoginContainer = styled.div`
  max-width: 480px;
  margin: 0 auto;
  padding: 20px;
  background-color: white;
  min-height: 100vh;
`;

const Title = styled.h1`
  font-size: 24px;
  margin-bottom: 10px;
`;

const Subtitle = styled.p`
  color: #666;
  margin-bottom: 30px;
`;

const FormGroup = styled.div`
  margin-bottom: 20px;
`;

const Label = styled.label`
  display: block;
  margin-bottom: 5px;
  color: #666;
  font-size: 14px;
`;

const StyledField = styled(Field)`
  width: 100%;
  padding: 12px;
  border: 1px solid #ddd;
  border-radius: 4px;
  font-size: 16px;
`;

const ErrorText = styled.div`
  color: red;
  font-size: 14px;
  margin-top: 5px;
`;

const LoginButton = styled.button`
  width: 100%;
  background-color: #ccc;
  color: white;
  border: none;
  border-radius: 4px;
  padding: 12px;
  font-size: 16px;
  cursor: pointer;
  margin-top: 20px;
  
  &:disabled {
    opacity: 0.7;
    cursor: not-allowed;
  }
  
  &.active {
    background-color: #6c25ff;
  }
`;

const AlertMessage = styled.div`
  background-color: #f8d7da;
  color: #721c24;
  padding: 10px;
  border-radius: 4px;
  margin-bottom: 20px;
`;

const validationSchema = Yup.object({
  email: Yup.string()
    .email('Invalid email address')
    .required('Email is required'),
  password: Yup.string()
    .min(6, 'Password must be at least 6 characters')
    .required('Password is required')
});

const Login = () => {
  const navigate = useNavigate();
  const [loginError, setLoginError] = useState('');

  const handleSubmit = async (values, { setSubmitting }) => {
    try {
      await authService.login(values.email, values.password);
      navigate('/account');
    } catch (error) {
      setLoginError('Invalid email or password. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <LoginContainer>
      <Title>Signin to your PopX account</Title>
      <Subtitle>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</Subtitle>
      
      {loginError && <AlertMessage>{loginError}</AlertMessage>}
      
      <Formik
        initialValues={{ email: '', password: '' }}
        validationSchema={validationSchema}
        onSubmit={handleSubmit}
      >
        {({ isSubmitting, isValid, dirty }) => (
          <Form>
            <FormGroup>
              <Label htmlFor="email">Email Address</Label>
              <StyledField type="email" id="email" name="email" placeholder="Enter email address" />
              <ErrorMessage name="email" component={ErrorText} />
            </FormGroup>
            
            <FormGroup>
              <Label htmlFor="password">Password</Label>
              <StyledField type="password" id="password" name="password" placeholder="Enter password" />
              <ErrorMessage name="password" component={ErrorText} />
            </FormGroup>
            
            <LoginButton 
              type="submit" 
              disabled={isSubmitting || !(isValid && dirty)}
              className={isValid && dirty ? 'active' : ''}
            >
              Login
            </LoginButton>
          </Form>
        )}
      </Formik>
    </LoginContainer>
  );
};

export default Login;
